<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import {workspace,addDomain} from '$lib/stores/workspace';let show=false,name='',query='',error='';$: filtered=$workspace.domains.filter(d=>d.name.includes(query.toLowerCase().trim()));function submit(){try{addDomain(name);name='';show=false;error=''}catch(e){error=e instanceof Error?e.message:'Could not add domain.'}}</script>
<Heading title="Domains" subtitle="Manage domains and subdomains independently of your projects."><button class="btn primary" on:click={()=>show=!show}><Icon name="Plus"/> Add domain</button></Heading><div class="stack">{#if show}<form class="card stack" on:submit|preventDefault={submit}><h3>Add domain</h3><label class="field">Domain name<input required bind:value={name} placeholder="example.com"/></label><p class="subtitle">No project required. No public DNS records will be changed.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn secondary" type="button" on:click={()=>show=false}>Cancel</button><button class="btn primary" type="submit">Add domain</button></div></form>{/if}<section class="card table-card"><div class="table-head"><div class="section-title"><h3>Domain inventory</h3><p class="subtitle">Use existing domains when a project needs them.</p></div><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search domains…" aria-label="Search domains"/></label></div></div><div class="table-wrap"><table><thead><tr><th>Domain / subdomain</th><th>Connected project</th><th>Status</th><th>SSL certificate</th></tr></thead><tbody>{#each filtered as d}<tr><td><div class="row"><span class="icon-box"><Icon name="Domains"/></span><span class="strong native-path">{d.name}</span></div></td><td>{#if d.project}<a href={'/projects/'+d.project+'/domains'} class="link-btn">{$workspace.projects.find(p=>p.id===d.project)?.name||d.project}</a>{:else}Unassigned{/if}</td><td><Status value={d.status}/></td><td><Status value={d.ssl?'Secured':'Not issued'}/></td></tr>{:else}<tr><td colspan="4">No domains found.</td></tr>{/each}</tbody></table></div></section></div>
